import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

public final class PoolLifecycleLab {
    /** Attach cleanup errors without replacing the primary error or self-suppressing. */
    static void record(Throwable primary, Throwable cleanup) {
        if (primary != cleanup) primary.addSuppressed(cleanup);
    }
    static final class NoSuppression extends Exception {
        NoSuppression() { super("suppression disabled", null, false, true); }
    }
    public static void main(String[] args) throws Exception {
        ThreadPoolExecutor pool = new ThreadPoolExecutor(1, 2, 1, TimeUnit.SECONDS,
                new ArrayBlockingQueue<>(1), new ThreadPoolExecutor.AbortPolicy());
        CountDownLatch firstStarted = new CountDownLatch(1), extraStarted = new CountDownLatch(1);
        CountDownLatch release = new CountDownLatch(1);
        AtomicInteger interrupted = new AtomicInteger();
        Callable<Integer> blocker = () -> {
            try { Checks.await(release); return 1; }
            catch (InterruptedException e) { interrupted.incrementAndGet(); throw e; }
        };
        try {
            Future<Integer> first = pool.submit(() -> { firstStarted.countDown(); return blocker.call(); });
            Checks.await(firstStarted);
            Future<Integer> queued = pool.submit(() -> 2);
            Future<Integer> extra = pool.submit(() -> { extraStarted.countDown(); return blocker.call(); });
            Checks.await(extraStarted);
            Checks.that(pool.getPoolSize() == 2 && pool.getQueue().size() == 1, "core -> queue -> max");
            try { pool.submit(() -> 4); throw new AssertionError("saturation accepted"); }
            catch (RejectedExecutionException expected) { }
            List<Runnable> neverStarted = pool.shutdownNow();
            Checks.that(neverStarted.size() == 1, "queued task returned");
            Checks.that(!queued.isDone(), "shutdownNow alone did not cancel returned FutureTask");
            for (Runnable task : neverStarted) if (task instanceof Future<?> f) f.cancel(false);
            Checks.that(queued.isCancelled(), "owner gives unstarted future a terminal state");
            Checks.that(pool.awaitTermination(5, TimeUnit.SECONDS), "interruptible tasks ended");
            Checks.that(interrupted.get() == 2, "both running tasks observed interruption");
            for (Future<Integer> f : List.of(first, extra)) {
                try { Checks.get(f); throw new AssertionError("expected interrupted failure"); }
                catch (ExecutionException e) { Checks.that(e.getCause() instanceof InterruptedException, "cause"); }
            }
            try { pool.submit(() -> 5); throw new AssertionError("shutdown accepted"); }
            catch (RejectedExecutionException expected) { }
        } finally { release.countDown(); Checks.stop(pool); }
        ExecutorService single = Executors.newSingleThreadExecutor();
        try {
            Future<?> failed = single.submit(() -> { throw new IllegalStateException("business failure"); });
            try { Checks.get(failed); throw new AssertionError("failure hidden"); }
            catch (ExecutionException e) { Checks.that(e.getCause() instanceof IllegalStateException, "submit failure captured"); }
            Checks.that(Checks.get(single.submit(() -> 7)) == 7, "worker remains usable");
        } finally { Checks.stop(single); }
        CountDownLatch entered = new CountDownLatch(1), cooperate = new CountDownLatch(1), exited = new CountDownLatch(1);
        ExecutorService stubborn = Executors.newSingleThreadExecutor();
        try {
            Future<?> f = stubborn.submit(() -> {
                entered.countDown();
                try {
                    boolean done = false;
                    while (!done) {
                        try { done = cooperate.await(100, TimeUnit.MILLISECONDS); }
                        catch (InterruptedException ignored) { /* deliberate counterexample, bounded by owner */ }
                    }
                } finally { exited.countDown(); }
            });
            Checks.await(entered); f.cancel(true);
            Checks.that(f.isDone() && exited.getCount() == 1, "cancelled future != ended computation");
            cooperate.countDown(); Checks.await(exited);
        } finally { cooperate.countDown(); Checks.stop(stubborn); }
        Exception primary = new Exception("primary"), cleanup = new Exception("cleanup");
        record(primary, primary); record(primary, cleanup); record(primary, cleanup);
        Checks.that(primary.getSuppressed().length == 2, "same primary guarded; repeated secondary allowed");
        NoSuppression disabled = new NoSuppression(); record(disabled, disabled); record(disabled, cleanup);
        Checks.that(disabled.getSuppressed().length == 0, "suppression may be disabled");
        System.out.println("PoolLifecycleLab OK");
    }
}

import java.time.Duration;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import java.util.function.Function;

/** Five parallel inputs followed by one dependent computation. Executors belong to the caller. */
public final class AsyncWorkflowLab {
    public static final class Batch<R> {
        private final Object gate = new Object();
        private final List<FutureTask<?>> tasks = new ArrayList<>();
        private final CompletableFuture<R> result = new CompletableFuture<>();
        private final AtomicReference<ScheduledFuture<?>> alarm = new AtomicReference<>();
        public CompletionStage<R> stage() { return result.minimalCompletionStage(); }
        public boolean cancel() { return fail(new CancellationException("batch cancelled")); }
        private boolean fail(Throwable error) {
            boolean won = result.completeExceptionally(error);
            if (won) {
                List<FutureTask<?>> copy;
                synchronized (gate) { copy = List.copyOf(tasks); }
                for (FutureTask<?> task : copy) task.cancel(true);
            }
            return won;
        }
        private void enqueue(FutureTask<?> task, Executor executor) {
            synchronized (gate) {
                if (result.isDone()) { task.cancel(false); return; }
                tasks.add(task);
            }
            // Cancellation can race this call. A cancelled FutureTask.run does no user work.
            try { executor.execute(task); }
            catch (RuntimeException e) { fail(e); task.cancel(false); }
        }
        private void setAlarm(ScheduledFuture<?> scheduled) {
            alarm.set(scheduled);
            if (result.isDone()) scheduled.cancel(false);
        }
        private Batch() {
            result.whenComplete((v, e) -> {
                ScheduledFuture<?> scheduled = alarm.get();
                if (scheduled != null) scheduled.cancel(false);
            });
        }
    }
    private static <T> FutureTask<T> bridge(Callable<T> work, CompletableFuture<T> stage) {
        return new FutureTask<>(work) {
            protected void done() {
                try { stage.complete(get()); } // done() runs only after this FutureTask is terminal.
                catch (CancellationException e) { stage.completeExceptionally(e); }
                catch (ExecutionException e) { stage.completeExceptionally(e.getCause()); }
                catch (InterruptedException e) {
                    Thread.currentThread().interrupt(); stage.completeExceptionally(e);
                }
            }
        };
    }
    public static <T, R> Batch<R> start(List<? extends Callable<T>> inputs,
            Function<List<T>, R> sixth, ThreadPoolExecutor executor, ScheduledExecutorService timer,
            Duration timeout) {
        Objects.requireNonNull(sixth); Objects.requireNonNull(executor); Objects.requireNonNull(timer);
        if (!(executor.getRejectedExecutionHandler() instanceof ThreadPoolExecutor.AbortPolicy))
            throw new IllegalArgumentException("non-inlining AbortPolicy executor required");
        List<? extends Callable<T>> work = List.copyOf(inputs);
        if (work.size() != 5 || timeout.isNegative() || timeout.isZero()) throw new IllegalArgumentException();
        long nanos = timeout.toNanos();
        Batch<R> batch = new Batch<>();
        List<CompletableFuture<T>> stages = new ArrayList<>();
        List<FutureTask<T>> tasks = new ArrayList<>();
        for (Callable<T> input : work) {
            CompletableFuture<T> stage = new CompletableFuture<>();
            stages.add(stage); tasks.add(bridge(input, stage));
            stage.whenComplete((v, e) -> { if (e != null) batch.fail(e); });
        }
        CompletableFuture.allOf(stages.toArray(CompletableFuture[]::new)).thenRun(() -> {
            List<T> values = stages.stream().map(CompletableFuture::join).toList();
            CompletableFuture<R> sixthStage = new CompletableFuture<>();
            sixthStage.whenComplete((v, e) -> {
                if (e == null) batch.result.complete(v); else batch.fail(e);
            });
            batch.enqueue(bridge(() -> sixth.apply(values), sixthStage), executor);
        });
        try {
            batch.setAlarm(timer.schedule(() -> batch.fail(new TimeoutException("batch deadline")),
                    nanos, TimeUnit.NANOSECONDS));
            for (FutureTask<T> task : tasks) batch.enqueue(task, executor);
        } catch (RuntimeException e) { batch.fail(e); }
        return batch; // No get/join on incomplete work on the caller's path.
    }
    private static Throwable failure(Batch<?> batch) throws Exception {
        try { batch.stage().toCompletableFuture().get(5, TimeUnit.SECONDS); throw new AssertionError("expected failure"); }
        catch (ExecutionException e) { return e.getCause(); }
    }
    public static void main(String[] args) throws Exception {
        ThreadPoolExecutor pool = new ThreadPoolExecutor(5, 5, 0, TimeUnit.SECONDS,
                new ArrayBlockingQueue<>(5), new ThreadPoolExecutor.AbortPolicy());
        ScheduledExecutorService timer = Executors.newSingleThreadScheduledExecutor();
        CountDownLatch release = new CountDownLatch(1);
        try {
            CountDownLatch started = new CountDownLatch(5);
            List<Callable<Integer>> jobs = new ArrayList<>();
            for (int n = 1; n <= 5; n++) {
                int value = n;
                jobs.add(() -> { started.countDown(); Checks.await(release); return value; });
            }
            AtomicInteger sixthCalls = new AtomicInteger();
            Batch<Integer> ok = start(jobs, values -> {
                sixthCalls.incrementAndGet(); return values.stream().mapToInt(Integer::intValue).sum();
            }, pool, timer, Duration.ofSeconds(4));
            Checks.await(started);
            Checks.that(!ok.stage().toCompletableFuture().isDone(), "start returned while tasks still blocked");
            release.countDown();
            Checks.that(Checks.get(ok.stage().toCompletableFuture()) == 15 && sixthCalls.get() == 1, "five then sixth once");
            List<Callable<Integer>> broken = List.of(() -> 1, () -> { throw new IllegalArgumentException("input"); }, () -> 3, () -> 4, () -> 5);
            Batch<Integer> bad = start(broken, v -> { throw new AssertionError("sixth must not run"); }, pool, timer, Duration.ofSeconds(4));
            Checks.that(failure(bad) instanceof IllegalArgumentException, "input failure");
            ThreadPoolExecutor rejecting = new ThreadPoolExecutor(1, 1, 0, TimeUnit.SECONDS,
                    new ArrayBlockingQueue<>(1), new ThreadPoolExecutor.AbortPolicy());
            rejecting.shutdown();
            Checks.that(failure(start(jobs, v -> 0, rejecting, timer, Duration.ofSeconds(4))) instanceof RejectedExecutionException,
                    "submission rejection is terminal");
            CountDownLatch blocking = new CountDownLatch(1), cleanup = new CountDownLatch(1);
            List<Callable<Integer>> slow = List.of(() -> {
                blocking.countDown(); try { new CountDownLatch(1).await(); return 1; }
                finally { cleanup.countDown(); }
            }, () -> 2, () -> 3, () -> 4, () -> 5);
            Batch<Integer> timed = start(slow, v -> 0, pool, timer, Duration.ofMillis(300));
            Checks.await(blocking);
            Checks.that(failure(timed) instanceof TimeoutException, "overall deadline");
            Checks.await(cleanup); // Separately observe the cooperative operation's cleanup.
            Batch<Integer> cancelled = start(slow, v -> 0, pool, timer, Duration.ofSeconds(4));
            cancelled.cancel();
            Checks.that(failure(cancelled) instanceof CancellationException, "explicit cancellation");
            System.out.println("AsyncWorkflowLab OK");
        } finally { release.countDown(); Checks.stop(pool); Checks.stop(timer); }
    }
}

import java.util.concurrent.*;

/** Java 9+ API，使用 Java 21 实测：调用者的期限不能改写共享计算的结果。 */
public final class SharedTimeoutDemo {
    private static int assertions;
    private static void check(String name, boolean ok) {
        if (!ok) throw new AssertionError(name);
        assertions++;
        System.out.println("PASS " + name);
    }
    private static boolean timeoutResult(CompletableFuture<?> future) throws Exception {
        try { future.get(5, TimeUnit.SECONDS); return false; }
        catch (ExecutionException ex) {
            // copy 的异常可增加 CompletionException 包装，按因果链识别。
            Throwable cause = ex.getCause();
            while (cause instanceof CompletionException && cause.getCause() != null)
                cause = cause.getCause();
            return cause instanceof TimeoutException;
        }
        // get 本身的 TimeoutException 不捕获：它表示测试没完成，必须失败。
    }
    public static void main(String[] args) throws Exception {
        CompletableFuture<Integer> shared = new CompletableFuture<>();
        CompletableFuture<Integer> callerB = shared;
        CompletableFuture<Integer> callerA = shared.orTimeout(0, TimeUnit.NANOSECONDS);
        check("orTimeout 返回原对象", callerA == shared);
        // 根结果没有生产者，永远不会在定时器前完成；不依赖机器快慢。
        check("甲的期限使共享对象失败", timeoutResult(callerA));
        check("乙被同一个终态连带影响", timeoutResult(callerB));
        check("真实结果已无法覆盖超时终态", !shared.complete(42));

        CompletableFuture<Integer> source = new CompletableFuture<>();
        CompletableFuture<Integer> privateA = source.copy().orTimeout(0, TimeUnit.NANOSECONDS);
        CompletableFuture<Integer> privateB = source.copy();
        check("甲的私有视图按自己的期限失败", timeoutResult(privateA));
        check("甲超时不使源计算结束", !source.isDone());
        check("乙仍在等同一个源计算", !privateB.isDone());
        check("所有者仍能发布真实结果", source.complete(42));
        check("乙收到真实成功", privateB.get(5, TimeUnit.SECONDS) == 42);
        check("甲的终态保持超时", timeoutResult(privateA));

        CompletableFuture<Integer> nextSource = new CompletableFuture<>();
        CompletableFuture<Integer> cancelledView = nextSource.copy();
        check("只取消调用者自己的视图", cancelledView.cancel(true));
        check("视图取消不向源传播", !nextSource.isDone());
        nextSource.complete(7);
        check("源仍能成功而视图仍为取消", nextSource.join() == 7 && cancelledView.isCancelled());

        CompletionStage<Integer> readOnly = nextSource.minimalCompletionStage();
        CompletableFuture<Integer> clientCopy = readOnly.toCompletableFuture();
        // 客户端可改它拿到的副本，但不会拥有真实 source 的写权限。
        clientCopy.obtrudeValue(99);
        check("受限视图不会暴露源的完成权限", nextSource.join() == 7 && clientCopy.join() == 99);
        System.out.println("ASSERTIONS " + assertions);
    }
}

import java.util.concurrent.*;
import java.util.stream.*;

public final class ForkJoinLab {
    static final class Squares extends RecursiveTask<Long> {
        final int from, to;
        Squares(int from, int to) { this.from = from; this.to = to; }
        protected Long compute() {
            if (to - from <= 128) {
                long sum = 0;
                for (long x = from; x < to; x++) sum += x * x;
                return sum;
            }
            int middle = from + (to - from) / 2;
            Squares left = new Squares(from, middle); left.fork();
            long right = new Squares(middle, to).compute();
            return left.join() + right;
        }
    }
    public static void main(String[] args) throws Exception {
        ForkJoinPool pool = new ForkJoinPool(4);
        try {
            long expected = LongStream.range(0, 10000).map(x -> x * x).sum();
            long actual = pool.submit(new Squares(0, 10000)).get(5, TimeUnit.SECONDS);
            Checks.that(actual == expected, "CPU divide and conquer");
            long parallel = IntStream.range(0, 10000).parallel().mapToLong(x -> (long) x * x).sum();
            Checks.that(parallel == expected, "promotion before multiply");
            int single = IntStream.of(1, 2).reduce(10, Integer::sum);
            int split = IntStream.of(1).reduce(10, Integer::sum) + IntStream.of(2).reduce(10, Integer::sum);
            Checks.that(single == 13 && split == 23, "10 is not an addition identity");
            Checks.that(IntStream.range(0, 100).parallel().map(x -> x * 2).toArray().length == 100,
                    "collector/terminal ownership instead of shared ArrayList writes");
            System.out.println("ForkJoinLab OK");
        } finally { Checks.stop(pool); }
    }
}

import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

/** Java 21：分别约束已提交未回收任务数和进入远端的任务数。 */
public final class VirtualBudgetDemo {
    private static int assertions;
    private static void check(String name, boolean ok) {
        if (!ok) throw new AssertionError(name);
        assertions++;
        System.out.println("PASS " + name);
    }
    private static void await(CountDownLatch latch) throws InterruptedException {
        // 只作失败保险；顺序由门闩决定，不靠线程睡眠猜测。
        if (!latch.await(5, TimeUnit.SECONDS)) throw new AssertionError("gate stuck");
    }
    private static final class Probe {
        final Semaphore remote = new Semaphore(2);
        final CountDownLatch admitted = new CountDownLatch(1);
        final CountDownLatch started = new CountDownLatch(4);
        final CountDownLatch firstRemote = new CountDownLatch(2);
        final CountDownLatch release = new CountDownLatch(1);
        final AtomicInteger submitted = new AtomicInteger();
        final AtomicInteger activeRemote = new AtomicInteger();
        final AtomicInteger peakRemote = new AtomicInteger();
        final AtomicInteger peakWindow = new AtomicInteger();
        final AtomicInteger virtualTasks = new AtomicInteger();
    }
    private static int runBatch(Probe p, int count, int window) throws Exception {
        ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor();
        CompletionService<Integer> completed = new ExecutorCompletionService<>(executor);
        // 集合只保存当前窗口，不把全部 Future 永久留在内存。
        Set<Future<Integer>> outstanding = new HashSet<>();
        int next = 0, received = 0, total = 0;
        try {
            while (received < count) {
                while (next < count && outstanding.size() < window) {
                    final int item = next++;
                    Future<Integer> f = completed.submit(() -> {
                        if (Thread.currentThread().isVirtual()) p.virtualTasks.incrementAndGet();
                        p.started.countDown();
                        p.remote.acquire(); // 获得许可之前，不算进入远端。
                        int active = p.activeRemote.incrementAndGet();
                        p.peakRemote.accumulateAndGet(active, Math::max);
                        try {
                            p.firstRemote.countDown();
                            await(p.release); // 使测试能稳定观察第一批的状态。
                            return item + 1;
                        } finally {
                            p.activeRemote.decrementAndGet();
                            p.remote.release(); // 仅在 acquire 成功后归还。
                        }
                    });
                    outstanding.add(f);
                    p.submitted.incrementAndGet();
                    p.peakWindow.accumulateAndGet(outstanding.size(), Math::max);
                }
                p.admitted.countDown();
                Future<Integer> done = completed.poll(5, TimeUnit.SECONDS);
                if (done == null) throw new AssertionError("missing completion");
                outstanding.remove(done);
                total += done.get(); // 已完成，仍需 get 才会观察任务异常。
                received++;
            }
            return total;
        } finally {
            for (Future<?> f : outstanding) f.cancel(true);
            executor.shutdownNow();
            if (!executor.awaitTermination(5, TimeUnit.SECONDS))
                throw new AssertionError("virtual tasks did not stop");
        }
    }
    public static void main(String[] args) throws Exception {
        Probe p = new Probe();
        CompletableFuture<Integer> result = new CompletableFuture<>();
        Thread coordinator = Thread.ofPlatform().name("collector").start(() -> {
            try { result.complete(runBatch(p, 32, 4)); }
            catch (Throwable failure) { result.completeExceptionally(failure); }
        });
        try {
            await(p.admitted); await(p.started); await(p.firstRemote);
            check("入口窗口只提交四项", p.submitted.get() == 4);
            check("远端同时只有两项", p.activeRemote.get() == 2);
            check("等待远端的任务仍计入窗口", p.peakWindow.get() == 4);
            p.release.countDown();
            check("全部结果回收", result.get(5, TimeUnit.SECONDS) == 528);
            check("所有业务任务使用虚拟线程", p.virtualTasks.get() == 32);
            check("远端并发上限未被突破", p.peakRemote.get() == 2);
            check("入口上限未被突破", p.peakWindow.get() == 4);
            check("许可与活动计数全部归还", p.remote.availablePermits() == 2
                    && p.activeRemote.get() == 0);
        } finally {
            p.release.countDown();
            coordinator.join(5000);
            if (coordinator.isAlive()) {
                coordinator.interrupt(); coordinator.join(5000);
            }
            if (coordinator.isAlive()) throw new AssertionError("collector still alive");
        }
        System.out.println("ASSERTIONS " + assertions);
    }
}

import java.lang.management.ManagementFactory;
import java.util.*;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;

/** 虚拟线程释放载体，并不会替任务释放它持有的业务许可。 */
public final class PermitDependencyDemo {
    private static int assertions;
    private static void check(String name, boolean ok) {
        if (!ok) throw new AssertionError(name);
        assertions++;
        System.out.println("PASS " + name);
    }
    private static void await(CountDownLatch gate) throws InterruptedException {
        if (!gate.await(5, TimeUnit.SECONDS)) throw new AssertionError("gate stuck");
    }
    private static void badDependency() throws Exception {
        Semaphore quota = new Semaphore(2);
        ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor();
        CountDownLatch parentsOwnBoth = new CountDownLatch(2);
        CountDownLatch parentsWaiting = new CountDownLatch(2);
        CountDownLatch childrenAttempt = new CountDownLatch(2);
        CountDownLatch parentsStopped = new CountDownLatch(2);
        CountDownLatch childrenStopped = new CountDownLatch(2);
        List<Future<Integer>> parents = new ArrayList<>();
        Queue<Future<Integer>> children = new ConcurrentLinkedQueue<>();
        Queue<Long> virtualIds = new ConcurrentLinkedQueue<>();
        try {
            for (int i = 0; i < 2; i++) {
                parents.add(executor.submit(() -> {
                    boolean acquired = false;
                    try {
                        quota.acquire(); acquired = true;
                        virtualIds.add(Thread.currentThread().threadId());
                        parentsOwnBoth.countDown(); await(parentsOwnBoth);
                        Future<Integer> child = executor.submit(() -> {
                            boolean childAcquired = false;
                            try {
                                childrenAttempt.countDown();
                                quota.acquire(); childAcquired = true;
                                return 7;
                            } finally {
                                if (childAcquired) quota.release();
                                childrenStopped.countDown();
                            }
                        });
                        children.add(child);
                        parentsWaiting.countDown();
                        return child.get(); // 父任务仍持许可，却等待也需要许可的子任务。
                    } finally {
                        if (acquired) quota.release();
                        parentsStopped.countDown();
                    }
                }));
            }
            await(parentsWaiting); await(childrenAttempt);
            check("所有业务许可都在父任务手里", quota.availablePermits() == 0);
            check("两个子任务都已开始但不能取得许可", children.size() == 2
                    && children.stream().noneMatch(Future::isDone));
            check("两个父任务的结果都依赖子任务", parents.stream().noneMatch(Future::isDone));
            // Java 21 ThreadMXBean 的管理对象是平台线程，不能据其空结果排除虚拟线程问题。
            boolean invisible = virtualIds.stream().allMatch(id ->
                    ManagementFactory.getThreadMXBean().getThreadInfo(id) == null);
            check("Java21 ThreadMXBean 不提供这些虚拟线程详情", invisible);
        } finally {
            // 已用门闩确认四个任务开始，所以 finally 门闩确实应当到达。
            for (Future<?> f : children) f.cancel(true);
            for (Future<?> f : parents) f.cancel(true);
            executor.shutdownNow();
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) throw new AssertionError("tasks alive");
            // Future 被取消与 finally 已执行是不同事实，显式观察业务清理。
            await(parentsStopped); await(childrenStopped);
        }
        check("父子任务均完成清理", parentsStopped.getCount() == 0 && childrenStopped.getCount() == 0);
        check("取消回收后无许可泄漏", quota.availablePermits() == 2);
    }
    private static void flattenedDependency() throws Exception {
        Semaphore quota = new Semaphore(2);
        AtomicInteger active = new AtomicInteger(), peak = new AtomicInteger(), steps = new AtomicInteger();
        List<Future<Integer>> jobs = new ArrayList<>();
        ExecutorService executor = Executors.newVirtualThreadPerTaskExecutor();
        try {
            for (int i = 0; i < 20; i++) jobs.add(executor.submit(() -> {
                quota.acquire();
                int current = active.incrementAndGet();
                peak.accumulateAndGet(current, Math::max);
                try {
                    // 本例两步是顺序依赖；一个任务取得一次许可即可完成完整业务。
                    int first = 3; steps.incrementAndGet();
                    int second = first + 4; steps.incrementAndGet();
                    return second;
                } finally {
                    active.decrementAndGet(); quota.release();
                }
            }));
            int total = 0;
            for (Future<Integer> f : jobs) total += f.get(5, TimeUnit.SECONDS);
            check("展开依赖后全部业务成功", total == 140 && steps.get() == 40);
            check("修复未取消远端容量限制", peak.get() <= 2);
        } finally {
            for (Future<?> f : jobs) f.cancel(true);
            executor.shutdownNow();
            if (!executor.awaitTermination(5, TimeUnit.SECONDS)) throw new AssertionError("tasks alive");
        }
        check("修复方案也归还全部许可", quota.availablePermits() == 2 && active.get() == 0);
    }
